950: /// Internal, monotonic and idempotent future-outcome boundary for #186.
951: #[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
952: pub(crate) struct LocalProblemOutcomeInput {
953:     pub source_outcome_id: String,
954:     pub at_minute: StrategicMinute,
955:     pub mitigation_bps: u16,
956:     pub resolve: bool,
957: }
958: pub(crate) fn apply_outcome(
959:     ctx: &ReducerContext,
960:     problem_id: &str,
961:     input: &LocalProblemOutcomeInput,
962: ) -> Result<(), String> {
963:     if input.source_outcome_id.is_empty()
964:         || input.source_outcome_id.len() > 160
965:         || input.mitigation_bps > adventuresim_world_schema::BASIS_POINTS_PER_WHOLE
966:     {
967:         return Err("Invalid source outcome ID".into());
968:     }
969:     let fingerprint =
970:         serde_json::to_string(input).map_err(|_| "Could not encode outcome payload")?;
971:     let receipt_id = format!("{problem_id}:{}", input.source_outcome_id);
972:     if let Some(existing) = ctx
973:         .db
974:         .local_problem_outcome_receipt()
975:         .id()
976:         .find(&receipt_id)
977:     {
978:         return if existing.payload_fingerprint == fingerprint {
979:             Ok(())
980:         } else {
981:             Err("Conflicting retry for source outcome ID".into())
982:         };
983:     }
984:     if input.at_minute != official_minute(ctx) {
985:         return Err("Outcome minute is not the authoritative strategic minute".into());
986:     }
987:     let mut problem = ctx
988:         .db
989:         .local_problem_authority()
990:         .id()
991:         .find(problem_id.to_owned())
992:         .ok_or("Local problem not found")?;
993:     problem.mitigation_bps = problem.mitigation_bps.max(input.mitigation_bps);
994:     if input.resolve {
995:         problem.resolved_at = Some(
996:             problem
997:                 .resolved_at
998:                 .map_or(input.at_minute, |old| old.min(input.at_minute)),
999:         );
1000:     }
1001:     ctx.db
1002:         .local_problem_authority()
1003:         .id()
1004:         .update(problem.clone());
1005:     if (input.resolve
1006:         || problem.mitigation_bps == adventuresim_world_schema::BASIS_POINTS_PER_WHOLE)
1007:         && let Some(mut symptom) = ctx
1008:             .db
1009:             .local_problem_symptom()
1010:             .problem_id()
1011:             .find(problem_id.to_owned())
1012:     {
1013:         symptom.active_until = symptom.active_until.min(input.at_minute);
1014:         ctx.db.local_problem_symptom().problem_id().update(symptom);
1015:     }
1016:     ctx.db
1017:         .local_problem_outcome_receipt()
1018:         .insert(LocalProblemOutcomeReceipt {
1019:             id: receipt_id,
1020:             problem_id: problem_id.into(),
1021:             source_outcome_id: input.source_outcome_id.clone(),
1022:             applied_at: input.at_minute,
1023:             mitigation_bps: input.mitigation_bps,
1024:             resolved: input.resolve,
1025:             payload_fingerprint: fingerprint,
1026:         });
1027:     Ok(())

