128:           const result = await exchange(worker, { kind: "generate", job, dependencies });
129:           if (phase === "closed") throw new GenerationPoolError("cancelled", "Scene generation cancelled");
130:           await receive({ job, bytes: result.bytes, workerMilliseconds: result.milliseconds });
131:           if (phase === "closed") throw new GenerationPoolError("cancelled", "Scene generation cancelled");
132:         }
133:       }).map(promise => promise.catch(error => { failed = true; throw error; })));
134:     } catch (error) {
