311: fn load_world_dump(world: &mut World) {
312:     let Some(path) = world.resource::<Args>().world_dump.clone() else {
313:         return;
314:     };
315:     let bytes = match std::fs::read(&path) {
316:         Ok(bytes) => bytes,
317:         Err(error) => {
318:             error!(?error, path = %path.display(), "Failed to read world dump");
319:             return;
320:         }
321:     };
322:     let registry = world.resource::<AppTypeRegistry>().0.clone();
323:     let scene = {
324:         let registry = registry.read();
325:         let mut deserializer = match ron::de::Deserializer::from_bytes(&bytes) {
326:             Ok(deserializer) => deserializer,
327:             Err(error) => {
328:                 error!(?error, path = %path.display(), "Failed to parse world dump RON");
329:                 return;
330:             }
331:         };
332:         let scene_deserializer = bevy::world_serialization::serde::WorldDeserializer {
333:             type_registry: &registry,
334:             load_from_path: &mut NoAssetHandlesInDump,
335:         };
336:         match serde::de::DeserializeSeed::deserialize(scene_deserializer, &mut deserializer)
337:             .map_err(|error| deserializer.span_error(error))
338:         {
339:             Ok(scene) => scene,
340:             Err(error) => {
341:                 error!(?error, path = %path.display(), "Failed to deserialize world dump");
342:                 return;
343:             }
344:         }
345:     };
346: 
347:     let mut entity_map = bevy::ecs::entity::EntityHashMap::default();
348:     let result = scene.write_to_world(world, &mut entity_map);
349:     // Every loaded entity that had `Player` (or `SceneTerrain`) just
350:     // triggered `on_player_added`/`on_scene_terrain_added`, which queue
351:     // their derived components via `Commands` - flush now so the world is
352:     // fully ready before anything else runs this frame.
353:     world.flush();
354:     mark_loaded_items_replicated(world, entity_map.values());
355:     match result {
356:         Ok(()) => info!(
357:             path = %path.display(),
358:             entities = entity_map.len(),
359:             "Loaded world dump"
360:         ),
361:         Err(error) => error!(?error, path = %path.display(), "Failed to apply world dump"),
362:     }
363: }
