692:     let rut_offset = (half_width * 0.46).clamp(0.38, 0.82);
693:     let rut_width = (half_width * 0.12).clamp(0.14, 0.27);
694:     let gaussian = |distance: f32| (-(distance / rut_width).powi(2) * 1.7).exp();
695:     let ruts = gaussian(across - rut_offset) + gaussian(across + rut_offset);
696:     let crown = (1.0 - (across / half_width).powi(2)).max(0.0) * 0.026;
697:     let travelled = point.dot(tangent);
698:     let irregularity = signed_ground_noise(
699:         streams::ROAD_RUT.seed(seed, &[]),
700:         Vec2::new(travelled / 2.4, across / 1.1),
701:     ) * 0.004;
702:     (crown - ruts * 0.038 + irregularity).clamp(-0.048, 0.032)
703: }
