345: #[derive(Clone, Copy, Debug, Default, PartialEq)]
346: pub struct MeterVector(pub [f32; METER_COUNT]);
347: 
348: impl MeterVector {
349:     pub const ZERO: Self = Self([0.0; METER_COUNT]);
350: 
351:     pub fn from_entries(entries: &[(Meter, f32)]) -> Self {
352:         let mut values = [0.0; METER_COUNT];
353:         for (meter, value) in entries {
354:             values[meter.index()] =
355:                 (values[meter.index()] + finite_or_zero(*value)).clamp(-1.0, 2.0);
356:         }
357:         Self(values)
358:     }
359: 
360:     pub fn get(self, meter: Meter) -> f32 {
361:         self.0[meter.index()]
362:     }
363: 
364:     pub fn add_bounded(&mut self, other: Self) {
365:         for meter in Meter::ALL {
366:             let i = meter.index();
367:             self.0[i] = (finite_or_zero(self.0[i]) + finite_or_zero(other.0[i])).clamp(-1.0, 2.0);
368:         }
369:     }
370: 
371:     pub fn scaled(self, amount: f32) -> Self {
372:         let amount = finite_or_zero(amount).clamp(-16.0, 16.0);
373:         Self(
374:             self.0
375:                 .map(|value| (finite_or_zero(value) * amount).clamp(-1.0, 2.0)),
376:         )
377:     }
378: 
379:     pub fn terminal(self) -> Option<Meter> {
380:         Meter::ALL
381:             .into_iter()
382:             .filter(|meter| self.get(*meter) >= meter.terminal_loss())
383:             // Meter order is the canonical deterministic tie-break.
384:             .min()
385:     }
386: }
387: 
388: fn finite_or_zero(value: f32) -> f32 {
389:     if value.is_finite() { value } else { 0.0 }
390: }
391: 
392: pub fn humours(meters: MeterVector) -> [f32; HUMOUR_COUNT] {
393:     let mut result = [0.0; HUMOUR_COUNT];
394:     for meter in Meter::ALL {
395:         let deviation = meters.get(meter);
396:         for humour in 0..HUMOUR_COUNT {
397:             result[humour] += deviation * HUMOUR_WEIGHTS[meter.index()][humour];
398:         }
399:     }
400:     result.map(|value| value.clamp(-1.0, 1.0))
401: }
402: 
403: pub fn regional_humours(
404:     regional_meters: &[MeterVector; REGION_COUNT],
405: ) -> [[f32; HUMOUR_COUNT]; REGION_COUNT] {
406:     regional_meters.map(humours)
