1005:     }
1006:     let site = ctx
1007:         .db
1008:         .case_site_authority()
1009:         .id_key()
1010:         .find(case_site_id.to_string())
1011:         .filter(|site| site.id == *case_site_id && site.case_id == case_id)
1012:         .ok_or("Hostile resolution case-site authority is stale")?;
1013:     if group.case_site_id != *case_site_id {
1014:         return Err("Hostile resolution does not match the hostile-group site".into());
1015:     }
1016:     if let Some(mission_id) = mission_id {
1017:         let mission = ctx
1018:             .db
1019:             .mission_authority()
1020:             .id()
1021:             .find(mission_id.to_string())
1022:             .ok_or("Mission authority not found")?;
1023:         if mission.party_id != party_id
1024:             || mission.hostile_group_id.as_deref() != Some(hostile_group_id)
1025:             || mission.observer_character_id != observer_character_id
1026:             || mission.case_id != case_id
1027:             || mission.case_site_id.as_ref() != Some(case_site_id)
1028:             || mission.status != MissionAttemptStatus::Bound
