579:             .map_err(str::to_owned)?;
580:         if add > 0 {
581:             add_inventory_item(ctx, character_id, item_id, add);
582:             return Ok(());
583:         }
584:         if remove > 0 {
585:             let instances: Vec<_> = ctx
586:                 .db
587:                 .inventory_item()
588:                 .character_and_item_id()
589:                 .filter((character_id, item_id))
