627:     }
628:     let food = ctx
629:         .db
630:         .item()
631:         .id()
632:         .find(item_id.to_owned())
633:         .is_some_and(|definition| definition.kind == CatalogItemKind::Food)
634:         || adventuresim_core::food::definition(item_id).is_some();
635:     let measured = crate::inventory_amount::is_measured_item(ctx, item_id);
636:     if measured {
