644:             let mut items: Vec<_> = ctx
645:                 .db
646:                 .inventory_item()
647:                 .character_and_item_id()
648:                 .filter((character_id, item_id))
649:                 .collect();
650:             items.sort_by_key(|row| row.id);
651:             if items.iter().map(|row| row.quantity as u64).sum::<u64>() < remaining as u64 {
652:                 return Err("not enough inventory quantity to remove".into());
653:             }
654:             for mut row in items {
655:                 let take = row.quantity.min(remaining);
656:                 if food {
657:                     crate::food::remove_lot_quantity(ctx, row.id, take, row.quantity)?;
658:                 }
659:                 row.quantity -= take;
660:                 remaining -= take;
661:                 if row.quantity == 0 {
662:                     ctx.db
663:                         .inventory_item_amount()
664:                         .inventory_item_id()
665:                         .delete(row.id);
666:                     ctx.db.inventory_item().id().delete(row.id);
667:                 } else {
