681:         .filter((character_id, item_id))
682:         .collect::<Vec<_>>();
683:     items.sort_by_key(|item| item.id);
684:     if by_quantity > 0 {
685:         let addition = by_quantity as u32;
686:         if let Some(mut item) = items.into_iter().next() {
687:             if let Some(quantity) = item.quantity.checked_add(addition) {
688:                 item.quantity = quantity;
689:                 ctx.db.inventory_item().id().update(item);
690:             } else {
691:                 add_inventory_item(ctx, character_id, item_id, addition);
692:             }
693:         } else {
694:             add_inventory_item(ctx, character_id, item_id, addition);
695:         }
696:     } else if by_quantity < 0 {
697:         let available = items
698:             .iter()
699:             .map(|item| u64::from(item.quantity))
700:             .sum::<u64>();
701:         let mut remaining = u64::from(by_quantity.unsigned_abs());
702:         if available < remaining {
703:             return Err("not enough inventory quantity to remove".into());
704:         }
705:         for mut item in items {
706:             let taken = remaining.min(u64::from(item.quantity)) as u32;
707:             item.quantity -= taken;
708:             remaining -= u64::from(taken);
709:             if item.quantity == 0 {
