12: pub(super) fn provision_generated_weapon_carry(
13:     ctx: &ReducerContext,
14:     character_id: u64,
15: ) -> Result<(), String> {
16:     let sheathable: Vec<_> = ctx
17:         .db
18:         .inventory_item()
19:         .character_id()
20:         .filter(character_id)
21:         .filter(|inventory| {
22:             adventuresim_core::item_catalog::is_sheathable_weapon(&inventory.item_id)
23:         })
24:         .collect();
25:     if sheathable.is_empty() {
26:         return Ok(());
27:     }
28:     if sheathable.len() > 2 {
29:         return Err(format!(
30:             "Generated loadout has {} sheathable weapons but the authored belt kit carries at most two",
31:             sheathable.len()
32:         ));
33:     }
34: 
35:     let belt =
36:         add_inventory_item(ctx, character_id, BELT_ID, 1).ok_or("Could not add generated belt")?;
37:     let belt_placement = authored_placement_index(ctx, BELT_ID, WORN_PLACEMENT_ID)?;
38:     equip_equipment_internal(
39:         ctx,
40:         character_id,
41:         belt,
42:         belt_placement,
43:         Vec::new(),
44:         false,
45:         false,
46:     )?;
47: 
48:     for (weapon, hip) in sheathable.iter().zip(WEAPON_CARRY_HIP_PLACEMENTS) {
49:         let holder_id = match adventuresim_weapon_model::recommended_holder(&weapon.item_id) {
