51:             Some(adventuresim_weapon_model::WeaponHolderKind::HaftLoop) => HAFT_LOOP_ID,
52:             None => {
53:                 return Err(format!(
54:                     "Sheathable weapon {} has no procedural holder",
55:                     weapon.item_id
56:                 ));
57:             }
58:         };
59:         let holder = add_inventory_item(ctx, character_id, holder_id, 1)
60:             .ok_or_else(|| format!("Could not add generated {holder_id}"))?;
61:         crate::weapon_instance::fit_personal_holder(ctx, character_id, holder, weapon.id)?;
62:         let holder_placement = authored_placement_index(ctx, holder_id, hip)?;
