426: pub fn piecewise(curve: &MeterCurve, age: u64) -> f32 {
427:     let Some(first) = curve.points.first() else {
428:         return 0.0;
429:     };
430:     if age <= first.minute {
431:         return finite_or_zero(first.loss);
432:     }
433:     for pair in curve.points.windows(2) {
434:         let [left, right] = pair else { unreachable!() };
435:         if age <= right.minute {
436:             let span = right.minute.saturating_sub(left.minute);
437:             if span == 0 {
438:                 return finite_or_zero(right.loss);
439:             }
440:             let fraction = age.saturating_sub(left.minute) as f64 / span as f64;
441:             return (left.loss as f64 + (right.loss - left.loss) as f64 * fraction) as f32;
442:         }
443:     }
444:     finite_or_zero(curve.points.last().expect("nonempty curve").loss)
445: }
